import {$,shell,t,complete} from './shared.js';
import {questions,planets} from './content.js';
import {setMascotState} from './mascot.js';
shell('missions');
function mascotMood(state,message){$('activity-companion').hidden=false;setMascotState($('activity-mascot').querySelector('.mascot'),state);$('mascot-message').textContent=message}

$('close-dialog').onclick=()=>$('activity').close();
let qi=0,score=0;function quiz(){mascotMood('thinking','Let’s think together.');const q=questions[qi];$('activity-content').innerHTML=`<p class="tag">0${qi+1} / 03</p><h3>${q[0]}</h3><div class="answers">${q[1].map((a,i)=>`<button class="answer" data-answer="${i}">${a}</button>`).join('')}</div><p class="feedback" role="status"></p>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const right=Number(b.dataset.answer)===q[2];if(right)score++;mascotMood(right?'done':'oops',right?'Great! Let’s keep exploring.':'That’s okay — we’re learning.');document.querySelectorAll('[data-answer]').forEach(a=>{a.disabled=true;if(Number(a.dataset.answer)===q[2])a.classList.add('correct')});if(!right)b.classList.add('wrong');document.querySelector('.feedback').textContent=right?t('correct'):`${t('wrong')} ${q[1][q[2]]}`;const next=document.createElement('button');next.className='button';next.textContent=t('next');next.onclick=()=>{qi++;if(qi<3)quiz();else{if(score===3)complete('quiz');mascotMood(score===3?'done':'talking',score===3?t('done'):'Shall we try again?');$('activity-content').innerHTML=`<h3>${score===3?t('done'):t('result')}</h3><p>${t('result')}: ${score} ${t('of')} 3</p><button class="button" id="retry">${t('retry')}</button>`;$('retry').onclick=()=>{qi=0;score=0;quiz()}}};$('activity-content').append(next)})}
$('quiz-open').onclick=()=>{qi=0;score=0;quiz();$('activity').showModal()};
let order=[];const shuffled=[4,0,6,2,7,1,5,3];function game(){mascotMood('thinking','Let’s find each planet’s place.'); $('activity-content').innerHTML=`<h3>${t('gameTitle')}</h3><p>${t('order')}</p><p class="selected-order">${order.map(i=>planets[i].name).join(' → ')||'—'}</p><div class="order-list">${shuffled.map(i=>`<button class="answer" data-planet="${i}" ${order.includes(i)?'disabled':''}>${planets[i].name}</button>`).join('')}</div><p class="feedback" role="status"></p><button class="button" id="check" ${order.length<8?'disabled':''}>${t('check')}</button> <button class="text-button" id="reset">${t('reset')}</button>`;document.querySelectorAll('[data-planet]').forEach(b=>b.onclick=()=>{order.push(Number(b.dataset.planet));game()});$('reset').onclick=()=>{order=[];game()};$('check').onclick=()=>{const right=order.every((v,i)=>v===i);document.querySelector('.feedback').textContent=t(right?'orderRight':'orderWrong');mascotMood(right?'done':'oops',right?t('done'):'Let’s try another order.');if(right)complete('game')}}
$('game-open').onclick=()=>{order=[];game();$('activity').showModal()};
